import{I as o,o as d,c as u,j as t,a as i,J as s,w as r,b6 as g}from"./chunks/framework.COUcLbTA.js";const h={style:{margin:"50px 0"}},P=JSON.parse('{"title":"找到好点子 - 从用户需求到有人买单","description":"学习如何从日常痛点中发现商业机会，掌握需求分析的系统方法论，把普通想法打磨成用户愿意付费的产品概念。","frontmatter":{"title":"找到好点子 - 从用户需求到有人买单","description":"学习如何从日常痛点中发现商业机会，掌握需求分析的系统方法论，把普通想法打磨成用户愿意付费的产品概念。"},"headers":[],"relativePath":"zh-cn/stage-1/finding-great-idea/index.md","filePath":"zh-cn/stage-1/finding-great-idea/index.md"}'),q={name:"zh-cn/stage-1/finding-great-idea/index.md"},m=Object.assign(q,{setup(c){const a="约 <strong>3 小时</strong>";return(b,l)=>{const p=o("ChapterIntroduction"),n=o("StepBar"),e=o("ClientOnly");return d(),u("div",null,[l[1]||(l[1]=t("h1",{id:"初级二-找到好点子",tabindex:"-1"},[i("初级二：找到好点子 "),t("a",{class:"header-anchor",href:"#初级二-找到好点子","aria-label":"Permalink to “初级二：找到好点子”"},"​")],-1)),l[2]||(l[2]=t("h2",{id:"本章导读",tabindex:"-1"},[i("本章导读 "),t("a",{class:"header-anchor",href:"#本章导读","aria-label":"Permalink to “本章导读”"},"​")],-1)),s(p,{duration:a,tags:["需求挖掘","产品思维","用户分析","商业模式"],coreOutput:"3 个经过验证的产品概念",expectedOutput:"可落地的创业/产品方向"},{default:r(()=>[...l[0]||(l[0]=[t("p",null,[i("前面我们学会了用 AI IDE 做东西，但有一个更根本的问题："),t("strong",null,"做什么？")],-1),t("p",null,[i('很多人一上来就想"做个 AI 工具"、"搞个社交平台"，结果做出来的东西没人用。问题出在哪？'),t("strong",null,"没有找到真需求"),i("。")],-1),t("p",null,[i("更残酷的现实是："),t("strong",null,"很多产品虽然解决了问题，但用户就是不愿意买单。")],-1),t("p",null,"这一章，我们将通过小明的故事，学习如何找到值得做的产品方向。",-1),t("p",null,[i("学完这一章，你将拥有一套"),t("strong",null,"完整的找点子方法论"),i("，以及 3 个经过验证的产品概念。")],-1)])]),_:1}),t("div",h,[s(e,null,{default:r(()=>[s(n,{active:0,items:[{title:"Step 1",description:"建立判断标准"},{title:"Step 2",description:"挖掘日常痛点"},{title:"Step 3",description:"横向切分人群"},{title:"Step 4",description:"纵向深挖场景"},{title:"Step 5",description:"验证需求真伪"},{title:"Step 6",description:"打磨产品概念"}]})]),_:1})]),l[3]||(l[3]=g(`<h2 id="step-1-建立判断标准-——-什么样的需求用户愿意买单" tabindex="-1">Step 1：建立判断标准 —— 什么样的需求用户愿意买单 <a class="header-anchor" href="#step-1-建立判断标准-——-什么样的需求用户愿意买单" aria-label="Permalink to “Step 1：建立判断标准 —— 什么样的需求用户愿意买单”">​</a></h2><div class="warning custom-block"><p class="custom-block-title">为什么这一章很重要？</p><p>有人可能会觉得奇怪：&quot;这不是一门教 Vibe Coding 的课吗？为什么要先学&#39;找需求&#39;？直接开始写代码不行吗？&quot;</p><p>确实，市面上很多编程课都是直接教你做项目：做个 Todo List、做个计算器、做个个人博客……这些项目确实能帮你熟悉语法和工具，但问题是：</p><p><strong>方向错了，越深入错得越多。</strong></p><p>想象一下：</p><ul><li>你花两周时间做了一个&quot;日历管理系统&quot;，但市面上已经有 100 个更好的</li><li>你做了一个&quot;卡路里拍照计算&quot;，但用户用一次就卸载了</li><li>你做了一个&quot;个人记账本&quot;，但连你自己都懒得用</li></ul><p>这些项目做完，你能写在简历上吗？大概率不能，因为<strong>它们没有解决真实的问题，也没有产生真实的价值</strong>。</p><p>更残酷的是：既然我们要投入时间学习，为什么不追求更好的结果？</p><p>既然 Vibe Coding 让我们能快速把想法变成产品，那我们更应该学会<strong>找到值得做的想法</strong>。用最接近实战的方式来训练自己——不是做&quot;练习项目&quot;，而是做&quot;有人愿意用的产品&quot;。</p><p>这就是为什么我们要先学&quot;找到好点子&quot;。</p><hr><p><strong>笔者私以为</strong>，时间是很宝贵的，<strong>既然做，我们就做到最好</strong>，不然为什么不去玩呢？作为责任，笔者也会竭尽全力，支持你做到最好。</p><p>就算所有人都不相信你能做好，笔者也会坚定不移盼望着你能做到最好。选择了 vibecoding 做产品，那就试试看自己能到哪一个尽头吧！</p></div><hr><h2 id="开篇-独立开发程序员小明的故事" tabindex="-1">开篇：独立开发程序员小明的故事 <a class="header-anchor" href="#开篇-独立开发程序员小明的故事" aria-label="Permalink to “开篇：独立开发程序员小明的故事”">​</a></h2><p>小明是一名程序员，工作三年了。有一天他突然想到：要不做一个健身 APP 吧，帮用户制定健身计划、记录训练数据。这个想法让他很兴奋，觉得自己终于找到了一个可以做的项目。</p><p>接下来的一年，小明几乎把所有业余时间都搭进去了。他做了一个功能很全的 APP——课程模块、打卡系统、社区功能、数据分析，该有的都有。界面也做得挺好看，至少他自己觉得挺满意的。</p><p>上线那天，小明满怀期待。他花了不少钱做推广，第一个月就有 5 万人下载。看起来开局不错，对吧？</p><p>但很快问题就来了。用户下载之后，用一次就卸载了，7日留存只有 5%。他做了几个付费功能，但几乎没有用户愿意掏钱。更让他沮丧的是，Keep、薄荷健康、FitTime 这些成熟产品，功能比他全，内容比他好，用户为什么要换到他的 APP？</p><p>一年下来，小明亏了 20 万。</p><p>他坐在电脑前，看着后台惨淡的数据，心里只有一个问题：我的 APP 做得挺好的啊，为什么没人用？更没人愿意买单？</p><p>小明的失败，不是因为技术不行，也不是因为产品做得不好。说实话，他的 APP 功能挺全的，界面也挺好看的。</p><p><strong>问题出在起点。</strong></p><p>他从来没问过一个最基本的问题：用户真的需要吗？</p><p>他看到健身 APP 市场很大，Keep 估值多少亿，就觉得这是个好机会。但他没搞清楚几件事：用户为什么需要另一个健身 APP？和 Keep 相比，我的差异化是什么？用户愿意为此付费吗？</p><p><strong>方向错了，越深入错得越多。</strong> 他花了一年时间，把一个错误的方向做得越来越完善，结果只是离成功越来越远。</p><div class="tip custom-block"><p class="custom-block-title">这一章我们做什么</p><p>这一章，我们来帮小明复盘一下。看看他的问题到底出在哪，然后一起找到真正有人愿意买单的产品方向。</p><p>我们将分三步走：</p><p><strong>第一幕：找到真需求</strong> —— 先搞清楚什么样的需求用户才愿意买单</p><p><strong>第二幕：挖出好点子</strong> —— 学会从普通想法中挖掘出有价值的商业机会</p><p><strong>第三幕：AI对话打磨</strong> —— 用 AI 把想法变成可落地的产品方案</p></div><hr><h2 id="第一幕-找到真需求" tabindex="-1">第一幕：找到真需求 <a class="header-anchor" href="#第一幕-找到真需求" aria-label="Permalink to “第一幕：找到真需求”">​</a></h2><p>小明很沮丧，但没放弃。他开始反思一个问题：到底什么样的需求，用户才愿意买单？</p><h3 id="小明的困惑-为什么用户不买单" tabindex="-1">小明的困惑：为什么用户不买单？ <a class="header-anchor" href="#小明的困惑-为什么用户不买单" aria-label="Permalink to “小明的困惑：为什么用户不买单？”">​</a></h3><p>他去找了几个用过他 APP 的朋友，想听听他们的真实想法。</p><p>朋友 A 说：&quot;你这个 APP 做得挺好，但我已经在用 Keep 了，为什么要切换？&quot;</p><p>朋友 B 说：&quot;你让我记录每次训练，太麻烦了，我懒得记。&quot;</p><p>朋友 C 说得更直接：&quot;免费功能够用了，我为什么要付费？&quot;</p><p>这些回答让小明突然明白了问题在哪。</p><p><strong>第一个问题：用户不切换，是因为现有方案已经够好了。</strong> Keep 等成熟产品功能已经很全，用户习惯也养成了，迁移成本很高。你做一个差不多的产品，用户凭什么要换？</p><p><strong>第二个问题：用户不愿意改变习惯。</strong> 记录训练这件事，对用户来说太麻烦了。如果一个产品需要用户改变 3 个以上的习惯，大概率会失败。</p><p><strong>第三个问题：免费替代品太多。</strong> 你的功能太通用，没有独特价值，用户找不到付费的理由。</p><h3 id="什么是真需求" tabindex="-1">什么是真需求？ <a class="header-anchor" href="#什么是真需求" aria-label="Permalink to “什么是真需求？”">​</a></h3><p>小明开始研究那些让用户愿意买单的成功产品。他发现了一个共同点：这些产品解决的都不是&quot;我觉得有用&quot;的需求，而是用户愿意为之付费、愿意为之改变行为、愿意为之忍受不便的那种需求。</p><p>换句话说，<strong>真需求是用户用脚投票投出来的，不是产品经理拍脑袋想出来的。</strong></p><h3 id="案例-让用户买单的产品" tabindex="-1">案例：让用户买单的产品 <a class="header-anchor" href="#案例-让用户买单的产品" aria-label="Permalink to “案例：让用户买单的产品”">​</a></h3><p>小明研究了几个成功案例，想搞清楚它们到底抓住了什么痛点。</p><h4 id="美菜网-让小餐馆老板睡个好觉" tabindex="-1">美菜网：让小餐馆老板睡个好觉 <a class="header-anchor" href="#美菜网-让小餐馆老板睡个好觉" aria-label="Permalink to “美菜网：让小餐馆老板睡个好觉”">​</a></h4><p>表面上看，美菜网做的事情很简单：帮餐馆买菜。但如果你仔细想，餐馆老板为什么要用它？</p><p>因为小餐馆老板每天凌晨 4 点就要起床去批发市场，很辛苦，而且经常被坑。美菜网做的事情，不是简单的&quot;电商卖菜&quot;，而是重构了整个供应链，让小餐馆老板能睡个好觉。</p><p>痛点越痛，付费意愿越强。省下的时间和体力，比省下的菜钱更有价值。</p><h4 id="小红书-解决选择困难" tabindex="-1">小红书：解决选择困难 <a class="header-anchor" href="#小红书-解决选择困难" aria-label="Permalink to “小红书：解决选择困难”">​</a></h4><p>表面上看，小红书是&quot;分享海外购物心得&quot;。但用户为什么愿意花时间在上面看笔记？</p><p>因为面对海量商品，用户不知道什么值得买、什么不值得买。他们需要一个信任的人帮自己筛选，节省时间，避免踩坑。</p><p>小红书解决的其实是两个深层痛点：选择困难和信任缺失。用户愿意为&quot;省时间&quot;和&quot;避坑&quot;付费，这就是为什么小红书能做起来。</p><hr><p>看完这些案例，小明有了一个重要发现。</p><p>用户买单的从来不是&quot;功能&quot;，而是&quot;解决恐惧&quot;和&quot;消除焦虑&quot;。美菜网解决的是小餐馆老板对凌晨采购艰辛的恐惧，小红书解决的是用户对买错东西的恐惧。</p><p><strong>恐惧驱动付费，焦虑驱动行动。</strong></p><h3 id="需求的三层-痛点、爽点、痒点" tabindex="-1">需求的三层：痛点、爽点、痒点 <a class="header-anchor" href="#需求的三层-痛点、爽点、痒点" aria-label="Permalink to “需求的三层：痛点、爽点、痒点”">​</a></h3><p>小明进一步研究，发现用户的需求可以分为三种类型：</p><div class="tip custom-block"><p class="custom-block-title">痛点（Pain Point）—— 恐惧驱动</p><p><strong>本质：</strong> 用户正在经历的、让他们感到痛苦、焦虑、不便的问题。不解决会很难受，甚至威胁到生存或安全。</p><p><strong>例子：</strong></p><ul><li>糖尿病患者不知道吃多少碳水会血糖飙升（恐惧：健康威胁）</li><li>小餐馆老板凌晨 4 点起床去批发市场（恐惧：生存艰辛）</li></ul><p><strong>关键：</strong> 用户愿意为此付费，因为不解决会&quot;很痛&quot;。</p></div><div class="tip custom-block"><p class="custom-block-title">爽点（Delight Point）—— 即时满足</p><p><strong>本质：</strong> 用户有一个需求，能够立即被满足，产生即时的愉悦感。</p><p><strong>例子：</strong></p><ul><li>外卖 30 分钟送达（即时满足饥饿）</li><li>一键生成精美 PPT（省时省力的爽感）</li></ul><p><strong>关键：</strong> 让用户&quot;爽&quot;是留存的关键，但单独作为付费点较弱。</p></div><div class="tip custom-block"><p class="custom-block-title">痒点（Itch Point）—— 虚拟自我</p><p><strong>本质：</strong> 用户想要变得更好、更酷、更精致，但不是必须的。满足了会开心，不满足也没事。</p><p><strong>例子：</strong></p><ul><li>记录每天喝了多少水（想象中的自律生活）</li><li>用 AI 给照片加艺术滤镜（想象中的艺术品味）</li></ul><p><strong>关键：</strong> 用户为&quot;痒点&quot;买单的意愿较弱，因为不解决也没事。</p></div><p>怎么看待正确的优先级排序？一个好的建议是：痛点 &gt; 爽点 &gt; 痒点</p><p>为什么？</p><ol><li><strong>痛点是生存需求：</strong> 不解决会死（或很难受），用户不得不买单。是&quot;止痛药&quot;。</li><li><strong>爽点是即时奖赏：</strong> 让用户爽，用户就会来。是&quot;海洛因&quot;（褒义的上瘾机制）。</li><li><strong>痒点是欲望满足：</strong> 可有可无，最容易被砍掉。是&quot;维生素&quot;或&quot;奢侈品&quot;。</li></ol><p><strong>关键洞察：</strong> 很多产品经理犯的错误是：用痛点的方式去推销痒点的产品。</p><p>比如：&quot;记录喝水能让你更健康&quot;——喝水确实健康，但不记录也不会不健康。这是把痒点包装成痛点，用户不会买账。</p><h3 id="验证真需求的5步法" tabindex="-1">验证真需求的5步法 <a class="header-anchor" href="#验证真需求的5步法" aria-label="Permalink to “验证真需求的5步法”">​</a></h3><p>小明想：<strong>那我有一个想法时，怎么快速判断它是否值得投入？</strong></p><p>他学习了产品经理常用的 5 步判断法（详细内容见附录A）：</p><ol><li><p><strong>第一步：直接和真实用户聊天，了解他们现在的做法</strong></p><p>找到 10 个目标用户。问他们：&quot;你现在怎么解决这个问题？&quot; 如果用户已经在用某种方法，说明问题确实存在。如果用户说不需要解决，那可能不是真需求。</p></li><li><p><strong>第二步：分析用户现有的替代方案，找出你的优势</strong></p><p>用户现在可能用其他产品、Excel、靠记忆，或者忍受着不解决。你需要弄清楚这些方案有什么缺点。你的产品要比它们好很多，用户才愿意换。</p></li><li><p><strong>第三步：测试用户是否愿意为你的产品付钱</strong></p><p>做预售或收定金。统计愿意付定金的用户比例（越早赚上钱说明需求越正确）：</p><ul><li>超过 10%：需求真实，值得投入</li><li>5% 到 10%：需求存在，但需要打磨</li><li>低于 5%：需求可能不成立</li></ul></li><li><p><strong>第四步：估算这个市场有多大，能不能赚钱</strong></p><p>计算三个数字：目标用户总数 × 付费意愿 × 客单价。相乘后得到市场规模。如果市场太小，可能不值得做。</p></li><li><p><strong>第五步：思考你的产品有什么护城河，防止别人抄袭</strong></p><p>考虑这些壁垒：技术难度、网络效应、品牌、成本优势。这些能帮你长期保持竞争力。</p></li></ol><p><strong>本幕小结：小明的收获</strong></p><ol><li><p><strong>真需求的标准</strong></p><ul><li>最重要的标准是用户愿意付费。</li><li>用户愿意为此改变行为。</li><li>没有解决方案时，用户会有很大损失。</li></ul></li><li><p><strong>避开假需求</strong></p><ul><li>痒点不是痛点，不能当成真需求。</li><li>市场太小，很难支撑商业模式。</li><li>方案比问题还复杂，用户会放弃。</li></ul></li><li><p><strong>优先级排序</strong></p><ul><li>真正的优先级是：痛点 &gt; 爽点 &gt; 痒点。</li></ul></li></ol><p><strong>本幕输出</strong></p><ul><li>我理解了什么是真需求。</li><li>我掌握了需求的三层分类：痛点、爽点、痒点。</li><li>我学会了用 5 步判断法验证需求真伪。</li></ul><hr><h2 id="第二幕-挖出好点子" tabindex="-1">第二幕：挖出好点子 <a class="header-anchor" href="#第二幕-挖出好点子" aria-label="Permalink to “第二幕：挖出好点子”">​</a></h2><p>小明现在知道了什么是真需求，但他还是不知道从哪里开始。总不能凭空想一个需求出来吧？</p><p>他决定从自己最熟悉的事情开始——身边的人和事。</p><h3 id="从自己出发-小明的姐姐" tabindex="-1">从自己出发：小明的姐姐 <a class="header-anchor" href="#从自己出发-小明的姐姐" aria-label="Permalink to “从自己出发：小明的姐姐”">​</a></h3><p>小明想起了他的姐姐。姐姐刚生完孩子，总是抱怨没时间健身，肚子上的赘肉减不下去，整个人很焦虑。</p><p>有一天小明问她：&quot;你现在怎么解决健身的问题？&quot;</p><p>姐姐叹了口气说：&quot;跟着 Keep 练吧，但那些动作不适合产后身体，做完腰更疼了。去健身房？没人帮忙看孩子。请私教？一节课 300 到 500 块，太贵了。自己瞎练吧，又怕受伤。&quot;</p><p>小明听完，觉得这可能就是他要找的真需求。</p><p>姐姐的困扰其实很具体：时间碎片化，需要照顾宝宝，没有整块时间健身；身体有限制，腹直肌分离、盆底肌松弛，不能剧烈运动；心理很焦虑，身材走样，担心老公嫌弃，社交自卑；信息太混乱，网上信息太多，不知道什么运动适合产后；还有孤独感，没人理解她们的处境，缺乏同伴支持。</p><p>这些都是真实的痛点，不是&quot;有也挺好&quot;的痒点。</p><hr><h3 id="横向切分-不同人群的需求" tabindex="-1">横向切分：不同人群的需求 <a class="header-anchor" href="#横向切分-不同人群的需求" aria-label="Permalink to “横向切分：不同人群的需求”">​</a></h3><p>小明意识到，&quot;健身 APP&quot;这个想法太泛了。他想做的是帮助所有人健身，但问题是，所有人的需求都不一样。</p><p>他做了一个横向切分，把&quot;想健身的人&quot;分成几类（详细方法见附录B）：</p><p>健身增肌人群需要精确计算蛋白质摄入，手动记录太麻烦，他们的付费意愿很高，追求效率。糖尿病患者必须严格控制碳水，但外出就餐很难估算，这是刚需，愿意付费，复购率也高。产后妈妈想恢复身材但没时间计算，需要简单方案，时间敏感，需要一站式服务。外卖党天天吃外卖不知道吃了多少热量，这是高频场景，但付费意愿中等。考研学生需要高效学习工具，但不知道用什么，这是刚需，但客单价低。</p><p>小明选择了&quot;产后妈妈&quot;这个人群。为什么？</p><p>首先，他自己就是用户——姐姐就是产后妈妈，他天然理解这个群体的痛点。其次，痛点很痛——产后恢复的焦虑是真实的，不是&quot;有也挺好&quot;的痒点。第三，付费意愿强——妈妈们为了恢复身材，愿意花钱。第四，竞争相对不激烈——市面上没有专门针对产后妈妈的产品。</p><div class="tip custom-block"><p class="custom-block-title">产品经理的切分逻辑</p><p>为什么切分人群这么重要？</p><p>因为通用工具很难赢。大平台已经占据了&quot;通用&quot;市场，你很难在功能上超越它们。细分人群的需求更痛——产后妈妈对健身的需求是刚需，普通健身者只是&quot;有也行&quot;。服务好一个小群体，比讨好所有人更容易建立口碑。细分人群的痛点更具体，更愿意为解决方案付费。</p></div><hr><h3 id="纵向深挖-完整的用户场景" tabindex="-1">纵向深挖：完整的用户场景 <a class="header-anchor" href="#纵向深挖-完整的用户场景" aria-label="Permalink to “纵向深挖：完整的用户场景”">​</a></h3><p>找到人群后，小明没有停留在&quot;产后健身&quot;这个单一功能上。他想更深入地理解用户的完整场景（详细方法见附录C）。</p><p>他观察了姐姐一天的生活。</p><p>早上 6 点，宝宝刚睡着，姐姐有 30 分钟空闲。她想运动，但怕吵醒宝宝，也不知道做什么动作安全。</p><p>上午 10 点，姐姐抱着宝宝哄睡，腰很酸。她想做一些修复运动，但手没空。</p><p>下午 3 点，宝宝睡觉，姐姐想运动。但身体很累，不知道还能不能做。</p><p>晚上 8 点，姐姐终于有空了，但很焦虑。她看着镜子里的自己，觉得人生完蛋了，翻着以前的照片偷偷哭。</p><p>小明发现，姐姐的痛点不是&quot;没有健身课程&quot;，而是&quot;产后恢复的恐惧和焦虑&quot;。</p><hr><div class="info custom-block"><p class="custom-block-title">产品经理的场景思维</p><p>很多人以为痛点就是功能需求，其实不是。痛点是场景中的情绪加上付费意愿。</p><p>产后妈妈面对镜子里走样的身材时，真正的痛点不是&quot;不知道怎么健身&quot;，而是恐惧——担心身体恢复不好，留下后遗症；焦虑——看着镜子里的自己，觉得人生完蛋了；无助——不知道从何开始，也没人指导；孤独——别人随便生，我却要恢复这么久。</p><p>好的产品设计，要解决的是情绪，而不只是功能。情绪背后，是用户付费的动力。</p></div><hr><h3 id="价值重构-从-健身app-到-产后妈妈恢复助手" tabindex="-1">价值重构：从&quot;健身APP&quot;到&quot;产后妈妈恢复助手&quot; <a class="header-anchor" href="#价值重构-从-健身app-到-产后妈妈恢复助手" aria-label="Permalink to “价值重构：从&quot;健身APP&quot;到&quot;产后妈妈恢复助手&quot;”">​</a></h3><p>基于以上分析，小明重新设计了这个产品。</p><div class="tip custom-block"><p class="custom-block-title">重构后的产品概念：&quot;产后妈妈恢复助手&quot;</p><p><strong>核心定位：</strong> 不只是健身工具，而是产后妈妈的&quot;专属康复教练+心理支持者&quot;</p><p><strong>核心功能：</strong></p><ol><li><p><strong>碎片化训练：</strong></p><ul><li>每次只需 10-15 分钟</li><li>宝宝睡觉时也能练</li><li>提供&quot;抱着宝宝也能做&quot;的动作</li></ul></li><li><p><strong>产后专属课程：</strong></p><ul><li>按产后阶段分级（0-3个月、3-6个月、6个月以上）</li><li>针对腹直肌分离、盆底肌修复的专项训练</li><li>每个动作都有&quot;产后注意事项&quot;提示</li></ul></li><li><p><strong>AI 动作纠正：</strong></p><ul><li>手机摄像头识别动作</li><li>实时提示&quot;膝盖太弯了&quot;、&quot;背部要挺直&quot;</li><li>避免错误动作伤害身体</li></ul></li><li><p><strong>心理支持社区：</strong></p><ul><li>只有产后妈妈的私密社区</li><li>分享恢复进度，互相鼓励</li><li>专业心理咨询师入驻</li></ul></li><li><p><strong>个性化方案：</strong></p><ul><li>根据生产方式（顺产/剖腹产）、身体情况定制</li><li>考虑哺乳期的特殊需求</li></ul></li></ol><p><strong>商业模式：</strong></p><ul><li>基础课程免费</li><li>高级课程：99元/月（含 AI 动作纠正、专属方案）</li><li>一对一私教：299元/月（线上指导）</li><li>社群会员：199元/年（含心理支持、专家答疑）</li></ul><p><strong>竞争壁垒：</strong></p><ul><li>专业性：与产后康复机构合作，有医学背书</li><li>社区粘性：产后妈妈的情感连接很强</li><li>数据积累：用户身体数据越多，方案越精准</li></ul><p><strong>市场规模：</strong></p><ul><li>中国每年新生儿约 1000万</li><li>产后康复市场约 500亿</li><li>目标：服务 1% 的产后妈妈 = 10万用户</li><li>ARPU（每用户平均收入）：500元/年</li><li>潜在收入：5000万/年</li></ul></div><p>对比原始 idea 和重构后的概念：</p><table tabindex="0"><thead><tr><th>维度</th><th>原始想法</th><th>重构后</th></tr></thead><tbody><tr><td>目标用户</td><td>所有健身人群（大而泛）</td><td>产后妈妈（精准）</td></tr><tr><td>解决痛点</td><td>记录训练（痒点）</td><td>产后恢复焦虑（痛点）</td></tr><tr><td>竞争壁垒</td><td>技术（容易被复制）</td><td>专业性+社区+数据</td></tr><tr><td>付费意愿</td><td>低（免费替代多）</td><td>高（刚需+情绪价值）</td></tr><tr><td>扩展空间</td><td>有限</td><td>可扩展到孕期、备孕期</td></tr></tbody></table><p><strong>这就是从&quot;一个功能&quot;到&quot;有人买单的产品&quot;的进化。</strong></p><hr><h3 id="更多例子-从普通idea到好点子" tabindex="-1">更多例子：从普通idea到好点子 <a class="header-anchor" href="#更多例子-从普通idea到好点子" aria-label="Permalink to “更多例子：从普通idea到好点子”">​</a></h3><p>小明觉得这个方法很好用。他又用同样的方法分析了几个其他例子，想看看这个方法是不是通用的（详细案例见附录D）。</p><h4 id="例子一-从-卡路里测量-到-糖友安心吃" tabindex="-1">例子一：从&quot;卡路里测量&quot;到&quot;糖友安心吃&quot; <a class="header-anchor" href="#例子一-从-卡路里测量-到-糖友安心吃" aria-label="Permalink to “例子一：从&quot;卡路里测量&quot;到&quot;糖友安心吃&quot;”">​</a></h4><p>普通想法是拍照识别食物热量，帮助减肥的人控制饮食。但问题是市面上已经有薄荷健康、MyFitnessPal 等成熟产品了。</p><p>小明横向切分了一下，发现糖尿病患者这个人群很有意思：他们必须严格控制碳水，但外出就餐很难估算。纵向深挖他们的场景：餐前不知道这个菜能不能吃，担心血糖飙升；餐中需要实时提醒&quot;你已经吃了多少碳水&quot;；餐后需要记录血糖变化，看和饮食的关系。</p><p>重构后的产品叫&quot;糖友安心吃&quot;，定位是糖尿病患者的&quot;饮食安全助手&quot;。</p><hr><h4 id="例子二-从-新闻助手-到-投研情报官" tabindex="-1">例子二：从&quot;新闻助手&quot;到&quot;投研情报官&quot; <a class="header-anchor" href="#例子二-从-新闻助手-到-投研情报官" aria-label="Permalink to “例子二：从&quot;新闻助手&quot;到&quot;投研情报官&quot;”">​</a></h4><p>普通想法是聚合各大平台新闻，省得一个个打开。但今日头条、腾讯新闻等已经做得很好了。</p><p>小明横向切分后发现，金融分析师这个人群有特殊需求：他们需要追踪特定行业动态，但信息太分散。纵向深挖他们的场景：早上看 overnight 美股动态、汇率变化；上午追踪持仓公司的公告、行业新闻；下午研究潜在投资标的，需要大量行业信息。</p><p>重构后的产品叫&quot;投研情报官&quot;，定位是金融从业者的&quot;信息雷达和决策助手&quot;。</p><hr><h4 id="例子三-从-校园二手平台-到-毕业清仓助手" tabindex="-1">例子三：从&quot;校园二手平台&quot;到&quot;毕业清仓助手&quot; <a class="header-anchor" href="#例子三-从-校园二手平台-到-毕业清仓助手" aria-label="Permalink to “例子三：从&quot;校园二手平台&quot;到&quot;毕业清仓助手&quot;”">​</a></h4><p>普通想法是校园二手交易平台。但闲鱼、转转已经做得很好了。</p><p>小明横向切分后发现，毕业生这个人群有特殊需求：东西太多，一个个卖太麻烦。纵向深挖他们的场景：毕业前一周就要离校，没时间慢慢卖；不知道谁需要我的东西；议价、交货、收款，太繁琐。</p><p>重构后的产品叫&quot;毕业清仓助手&quot;，定位是毕业生的&quot;离校资产管家&quot;。</p><hr><h3 id="本幕小结-小明的收获" tabindex="-1">本幕小结：小明的收获 <a class="header-anchor" href="#本幕小结-小明的收获" aria-label="Permalink to “本幕小结：小明的收获”">​</a></h3><p>通过第二幕，小明明白了：</p><p><strong>1. 从自己出发</strong></p><ul><li>你自己就是用户，天然理解这个群体的痛点</li><li>爱好是最好的起点，热情是最好的驱动力</li></ul><p><strong>2. 横向切分人群</strong></p><ul><li>不要服务&quot;所有人&quot;，找到&quot;最痛的那个人群&quot;</li><li>越细分，越有机会，用户付费意愿越强</li></ul><p><strong>3. 纵向深挖场景</strong></p><ul><li>描述完整的用户旅程：使用前、使用中、使用后</li><li>找到情绪触点：恐惧、焦虑、无助、孤独……</li></ul><p><strong>4. 价值重构</strong></p><ul><li>从&quot;功能&quot;升级为&quot;解决方案&quot;</li><li>从&quot;工具&quot;升级为&quot;助手/管家/伙伴&quot;</li></ul><hr><p>📦 <strong>本幕输出：</strong></p><ul><li>找到了一个精准的目标用户（产后妈妈）</li><li>理解了用户的完整场景和真实情绪</li><li>重构了产品概念，有了明确的差异化定位</li></ul><hr><h2 id="第三幕-ai对话打磨" tabindex="-1">第三幕：AI对话打磨 <a class="header-anchor" href="#第三幕-ai对话打磨" aria-label="Permalink to “第三幕：AI对话打磨”">​</a></h2><p>小明现在有了一个明确的产品方向：产后妈妈恢复助手。但他还是不知道具体怎么做，从哪里开始，技术实现难度大不大。</p><p>他决定用 AI 来帮助自己打磨产品概念，把想法变成可执行的计划。</p><h3 id="第一轮-抛出原始想法" tabindex="-1">第一轮：抛出原始想法 <a class="header-anchor" href="#第一轮-抛出原始想法" aria-label="Permalink to “第一轮：抛出原始想法”">​</a></h3><p>小明把他的想法告诉 AI：&quot;我想做一个产后妈妈恢复助手 APP，帮助产后妈妈恢复身材。但我担心技术实现难度，特别是 AI 动作纠正这个功能，我一个人能做吗？&quot;</p><hr><h3 id="第二轮-ai-帮助规划-mvp" tabindex="-1">第二轮：AI 帮助规划 MVP <a class="header-anchor" href="#第二轮-ai-帮助规划-mvp" aria-label="Permalink to “第二轮：AI 帮助规划 MVP”">​</a></h3><p>AI 回复说：&quot;很好的问题！让我们做一个 MVP（最小可行产品）规划。&quot;</p><p>AI 建议分三个阶段来做。第一阶段是 1-2 个月，目标是验证需求。不做 APP，先做一个微信小程序，只提供产后专属课程（视频）和打卡社区。用人工方式提供动作指导，用户上传视频，教练回复。目标是验证产后妈妈是否愿意付费。</p><p>第二阶段是 3-6 个月，如果第一阶段验证成功，就增加核心功能。开发 AI 动作纠正，可以用现成的 SDK，比如百度人体识别。增加个性化方案，优化社区功能。</p><p>第三阶段是 6-12 个月，规模化。开发独立 APP，与产后康复机构合作，拓展到孕期、备孕期。</p><p>关于技术实现，AI 建议 AI 动作纠正使用现成的 AI 能力，比如百度、腾讯的 API，不需要从零开发，降低成本。前期用人工加 AI 混合模式，逐步过渡。</p><p>启动成本方面，小程序开发 1-2 万（外包）或自己用 AI IDE 做，内容制作找产后康复教练合作，推广从妈妈群、小红书开始。</p><p>验证指标是第一个月 100 个用户，10% 付费转化率。如果达到，说明需求真实，继续投入；如果达不到，及时调整方向。</p><hr><h3 id="第三轮-小明提出担忧" tabindex="-1">第三轮：小明提出担忧 <a class="header-anchor" href="#第三轮-小明提出担忧" aria-label="Permalink to “第三轮：小明提出担忧”">​</a></h3><p>小明想了想，又问：&quot;我担心内容制作的问题。产后康复课程需要专业指导，我没有医学背景，怎么保证课程质量？&quot;</p><hr><h3 id="第四轮-ai-提供解决方案" tabindex="-1">第四轮：AI 提供解决方案 <a class="header-anchor" href="#第四轮-ai-提供解决方案" aria-label="Permalink to “第四轮：AI 提供解决方案”">​</a></h3><p>AI 回复说：&quot;这是很多技术型创业者的担忧，但有解决方案。&quot;</p><p>方案一是与专业人士合作。找产后康复教练、医院营养科医生合作，你提供技术和产品，他们提供专业内容，可以采用分成模式。</p><p>方案二是整合现有优质内容。初期可以用公开的产后康复视频，比如 YouTube、B站上的。自己做内容审核和整理，后期再制作原创内容。</p><p>方案三是用户生成内容。鼓励有经验的妈妈分享自己的恢复方法，用社区投票的方式筛选优质内容，逐步建立内容生态。</p><p>AI 建议先用方案一。具体操作是：找到 2-3 位产后康复教练，与他们谈合作，你开发产品，他们提供课程。收入分成，你拿 70%，他们拿 30%。这样既能保证内容质量，又能降低成本。前期课程制作 0 元，用分成模式，你只需要投入开发时间和推广成本。</p><p><strong>我的建议：先用方案一</strong></p><p>具体操作：</p><ol><li>找到 2-3 位产后康复教练</li><li>与他们谈合作：你开发产品，他们提供课程</li><li>收入分成：你拿 70%，他们拿 30%</li><li>这样既能保证内容质量，又能降低成本</li></ol><p><strong>前期成本：</strong></p><ul><li>课程制作：0 元（用分成模式）</li><li>你只需要投入开发时间和推广成本</li></ul><p>:::</p><hr><h3 id="第五轮-小明问推广问题" tabindex="-1">第五轮：小明问推广问题 <a class="header-anchor" href="#第五轮-小明问推广问题" aria-label="Permalink to “第五轮：小明问推广问题”">​</a></h3><p>小明还有最后一个担忧：&quot;推广成本会不会很高？怎么找到产后妈妈这个群体？&quot;</p><hr><h3 id="第六轮-ai-提供推广策略" tabindex="-1">第六轮：AI 提供推广策略 <a class="header-anchor" href="#第六轮-ai-提供推广策略" aria-label="Permalink to “第六轮：AI 提供推广策略”">​</a></h3><p>AI 回复说：&quot;产后妈妈这个群体其实很好找，推广成本可以很低。&quot;</p><p>最推荐的是小红书。搜索&quot;产后恢复&quot;、&quot;腹直肌分离&quot;等关键词，找到相关博主，私信合作。用&quot;免费体验 1 个月&quot;的方式换取推广，成本几乎为 0。</p><p>其次是妈妈群。搜索微信群、QQ 群，以&quot;产后恢复经验分享&quot;的名义进群，分享干货内容，不要直接广告，逐步建立信任。</p><p>还可以和医院妇产科合作，提供免费的产后恢复指导，在医院发放宣传单，成本就是印刷费几百元。或者和母婴店合作，放置宣传物料，购买母婴产品赠送体验卡，成本就是体验卡制作费。</p><p>验证指标是：第一个月 100 个用户，10 个付费用户（10% 转化率），总推广成本小于 1000 元，获客成本小于 10 元每人。如果能达到这个指标，说明需求真实，可以继续投入。</p><hr><h3 id="最终-小明有了清晰的计划" tabindex="-1">最终：小明有了清晰的计划 <a class="header-anchor" href="#最终-小明有了清晰的计划" aria-label="Permalink to “最终：小明有了清晰的计划”">​</a></h3><p>经过 6 轮对话，小明终于有了清晰的计划。</p><p>第一阶段是 1-2 个月：做一个微信小程序，找 2-3 位产后康复教练合作（分成模式），只提供产后专属课程（视频）和打卡社区，用人工方式提供动作指导。目标是 100 个用户，10% 付费转化率。</p><p>第二阶段是 3-6 个月：如果第一阶段验证成功，继续投入。增加 AI 动作纠正功能，增加个性化方案，优化社区功能。</p><p>第三阶段是 6-12 个月：开发独立 APP，与产后康复机构合作，拓展到孕期、备孕期。</p><p>启动成本很低：开发自己用 AI IDE 做（0 元），内容与教练分成（前期 0 元），推广用小红书加妈妈群（小于 1000 元）。总成本小于 1000 元。</p><hr><h3 id="ai-对话打磨的5步法" tabindex="-1">AI 对话打磨的5步法 <a class="header-anchor" href="#ai-对话打磨的5步法" aria-label="Permalink to “AI 对话打磨的5步法”">​</a></h3><p>通过这个案例，小明总结出了一个与 AI 对话的标准流程（详细内容见附录E）。</p><p><strong>第一步：抛出原始想法。</strong> 描述你的初步想法，哪怕很粗糙也没关系。告诉 AI 你的担忧，比如竞争激烈、不知道怎么差异化等。</p><p><strong>第二步：让 AI 帮你规划 MVP。</strong> 最小可行产品应该包含什么功能？分几个阶段？每个阶段的目标是什么？技术实现难度大吗？</p><p><strong>第三步：提出你的担忧。</strong> 技术实现难度？内容制作成本？推广成本？用户获取难度？把你的顾虑都告诉 AI。</p><p><strong>第四步：让 AI 提供解决方案。</strong> 针对你的担忧，AI 会给出具体建议。多个方案对比，选择最优。成本估算。</p><p><strong>第五步：最终确认计划。</strong> 整理一个清晰的行动计划，设定验证指标。如果达不到，及时调整方向。</p><p><strong>提示词模板：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一个 [产品概念]，</span></span>
<span class="line"><span>但我担心 [你的担忧]。</span></span>
<span class="line"><span>请帮我：</span></span>
<span class="line"><span>1. 规划一个 MVP</span></span>
<span class="line"><span>2. 给出具体的技术实现建议</span></span>
<span class="line"><span>3. 估算成本</span></span>
<span class="line"><span>4. 设定验证指标</span></span></code></pre></div><hr><h3 id="本幕小结-小明的收获-1" tabindex="-1">本幕小结：小明的收获 <a class="header-anchor" href="#本幕小结-小明的收获-1" aria-label="Permalink to “本幕小结：小明的收获”">​</a></h3><p>通过第三幕，小明明白了三件事。</p><p><strong>第一，用 AI 对话打磨产品概念。</strong> 不要期待一次对话就得到完美答案，多轮迭代。告诉 AI 你的观察、经历、身边人的反馈。如果 AI 的建议不合理，及时指出。最后一定要落到具体的行动计划。</p><p><strong>第二，MVP 的核心原则。</strong> 最小化，只做最核心的功能。可验证，能够快速验证需求是否真实。低成本，用最低的成本验证。</p><p><strong>第三，验证指标。</strong> 付费转化率大于 10%，说明需求真实，值得投入。付费转化率 5-10%，说明需求存在，但需要打磨。付费转化率小于 5%，说明需求不成立，及时调整。</p><hr><p>📦 <strong>本章输出：</strong></p><ul><li>有了清晰的 MVP 计划</li><li>知道了技术实现路径</li><li>设定了验证指标</li></ul><hr><h2 id="终章-你的行动" tabindex="-1">终章：你的行动 <a class="header-anchor" href="#终章-你的行动" aria-label="Permalink to “终章：你的行动”">​</a></h2><h3 id="记忆口诀" tabindex="-1">记忆口诀 <a class="header-anchor" href="#记忆口诀" aria-label="Permalink to “记忆口诀”">​</a></h3><p><strong>一人一事一切入，横切纵挖找痛点，AI对话磨概念，五步验证再动手</strong></p><p><strong>解释：</strong></p><ul><li><strong>一人：</strong> 从你自己出发，你天然理解这个群体</li><li><strong>一事：</strong> 聚焦一件具体的事情，不要贪多</li><li><strong>一切入：</strong> 找到切入点，越细分越好</li><li><strong>横切：</strong> 横向切分人群，找到最有付费意愿的用户</li><li><strong>纵挖：</strong> 纵向深挖场景，理解用户的完整旅程</li><li><strong>AI对话：</strong> 用 AI 对话打磨产品概念</li><li><strong>五步验证：</strong> 用 5 步判断法验证需求真伪</li></ul><hr><h3 id="课后练习" tabindex="-1">课后练习 <a class="header-anchor" href="#课后练习" aria-label="Permalink to “课后练习”">​</a></h3><p>选择一个你日常生活中的小麻烦，用本章的方法进行扩展：</p><div class="tip custom-block"><p class="custom-block-title">练习任务</p><p><strong>1. 描述这个麻烦</strong>（1 句话）</p><ul><li>例子：&quot;我想做一个记账 APP，帮助用户记录消费&quot;</li></ul><p><strong>2. 横向切分：找出 3 个可能有不同需求的人群</strong></p><ul><li>例子：小微企业主、留学生家长、自由职业者</li></ul><p><strong>3. 选择一个人群，纵向深挖：描述他们的完整场景和真实情绪</strong></p><ul><li>例子：留学生家长的场景——想知道孩子在外国花了多少钱，但孩子不说</li></ul><p><strong>4. 重构产品概念：从&quot;一个功能&quot;进化为&quot;一个解决方案&quot;</strong></p><ul><li>例子：&quot;留学资金管家&quot;——不只是记账，而是让家长对孩子的海外消费&quot;心中有数&quot;</li></ul><p><strong>5. 用验证清单评估你的想法</strong>（见附录F）</p><p><strong>把你的分析分享到社区，和其他学员讨论！</strong></p></div><hr><h2 id="附录-sop-方法论" tabindex="-1">附录：SOP 方法论 <a class="header-anchor" href="#附录-sop-方法论" aria-label="Permalink to “附录：SOP 方法论”">​</a></h2><h3 id="附录a-需求分析的5步判断法" tabindex="-1">附录A：需求分析的5步判断法 <a class="header-anchor" href="#附录a-需求分析的5步判断法" aria-label="Permalink to “附录A：需求分析的5步判断法”">​</a></h3><p>当你有一个想法时，如何快速判断它是否值得投入？</p><p><strong>第一步：用户验证——找到10个目标用户</strong></p><p><strong>不要问：</strong>&quot;你会用我的产品吗？&quot;（假阳性率90%）</p><p><strong>要问：</strong></p><ol><li>&quot;你现在怎么解决这个问题？&quot;（了解真实行为）</li><li>&quot;最近一周，这个问题让你困扰了几次？&quot;（了解频率）</li><li>&quot;为了解决它，你花了多少钱/时间？&quot;（了解付费意愿）</li><li>&quot;如果有个解决方案，但需要改变习惯，你愿意吗？&quot;（了解改变成本）</li></ol><p><strong>判断标准：</strong></p><ul><li>如果有3个以上用户说&quot;我每天都在为这事头疼&quot;——可能是痛点</li><li>如果用户说&quot;挺有意思，但我不着急&quot;——大概率是痒点</li><li>如果用户说&quot;我现在用XX解决，但不太满意&quot;——有机会</li></ul><p><strong>关键问题：</strong>用户现在用什么方法解决这个问题？</p><table tabindex="0"><thead><tr><th>替代方案类型</th><th>说明</th><th>机会判断</th></tr></thead><tbody><tr><td><strong>没有替代方案</strong></td><td>用户默默忍受</td><td>大机会，但需要教育市场</td></tr><tr><td><strong>用很笨的方法</strong></td><td>Excel、手工、多人协作</td><td>好机会，用户渴望更好的方案</td></tr><tr><td><strong>用多个工具拼凑</strong></td><td>A工具+B工具+C工具</td><td>好机会，整合有价值</td></tr><tr><td><strong>用成熟产品</strong></td><td>但用户不满意</td><td>有机会，但需要差异化</td></tr><tr><td><strong>用成熟产品</strong></td><td>用户很满意</td><td>机会很小，除非有颠覆式创新</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">什么是&quot;颠覆式创新&quot;？</p><p><strong>简单定义：</strong> 不是把产品做得更好，而是用更简单/便宜的方式，服务之前被忽视的用户群体。</p><p><strong>例子：</strong></p><ul><li>传统手机 → 智能手机（不是功能更多，而是交互方式完全不同）</li><li>传统出租车 → 滴滴（不是车更好，而是让叫车变得随时随地）</li><li>传统书店 → 电子书（不是书更多，而是让携带和购买更方便）</li></ul><p><strong>关键：</strong> 颠覆式创新往往从&quot;低端市场&quot;或&quot;新用户群体&quot;开始，逐步向上侵蚀。</p></div><p><strong>案例：</strong></p><ul><li>糖尿病患者现在用&quot;经验+猜测&quot;控制饮食（很笨的方法）——机会大</li><li>普通减肥者用薄荷健康（成熟产品，满意度中等）——有机会做细分</li><li>学生用微信群做二手交易（多个工具拼凑）——有机会做整合</li></ul><p><strong>最有效的方法：预售或定金</strong></p><p><strong>操作步骤：</strong></p><ol><li>做一个简单的落地页，描述你的产品概念</li><li>放上&quot;预售&quot;或&quot;预约&quot;按钮</li><li>看有多少人愿意付钱（哪怕只是1元）</li></ol><p><strong>判断标准：</strong></p><ul><li>愿意付定金的用户 &gt; 10%：需求真实，值得做</li><li>愿意付定金的用户 5-10%：需求存在，但需要打磨</li><li>愿意付定金的用户 &lt; 5%：需求不成立，或产品概念有问题</li></ul><p><strong>注意：</strong>说&quot;我会买&quot;的人很多，真正掏钱的人才是你的目标用户。</p><p><strong>简单公式：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>潜在市场规模 = 目标用户数量 × 付费意愿 × 客单价</span></span></code></pre></div><p><strong>案例：校园二手交易平台</strong></p><ul><li>目标用户：全国大学生 4000万</li><li>有二手交易需求的：50% = 2000万</li><li>愿意用平台的：10% = 200万</li><li>年交易频次：2次</li><li>平台抽成：5%</li><li>平均客单价：100元</li><li>潜在市场规模 = 200万 × 2 × 100 × 5% = 2000万/年</li></ul><p><strong>判断标准：</strong></p><ul><li>市场规模 &gt; 10亿：大赛道，值得做</li><li>市场规模 1-10亿：中小赛道，可以做但天花板明显</li><li>市场规模 &lt; 1亿：小众市场，适合副业或小而美</li></ul><p><strong>关键问题：</strong>如果产品做起来了，别人抄袭怎么办？</p><p><strong>常见的护城河类型：</strong></p><table tabindex="0"><thead><tr><th>护城河类型</th><th>说明</th><th>例子</th></tr></thead><tbody><tr><td><strong>网络效应</strong></td><td>用户越多，产品价值越大</td><td>微信、滴滴</td></tr><tr><td><strong>数据积累</strong></td><td>数据越多，算法越准</td><td>今日头条、抖音</td></tr><tr><td><strong>品牌认知</strong></td><td>用户心智占领</td><td>可口可乐、耐克</td></tr><tr><td><strong>规模效应</strong></td><td>规模越大，成本越低</td><td>京东物流、亚马逊</td></tr><tr><td><strong>技术专利</strong></td><td>核心技术壁垒</td><td>华为、大疆</td></tr><tr><td><strong>转换成本</strong></td><td>用户迁移成本高</td><td>企业软件、操作系统</td></tr></tbody></table><p><strong>早期项目的现实：</strong></p><ul><li>大部分早期项目没有明显的护城河</li><li>但不要紧，关键是<strong>跑得快</strong></li><li>先占领市场，再建立壁垒</li></ul><hr><h3 id="附录b-横向切分人群方法" tabindex="-1">附录B：横向切分人群方法 <a class="header-anchor" href="#附录b-横向切分人群方法" aria-label="Permalink to “附录B：横向切分人群方法”">​</a></h3><p>不要试图服务&quot;所有XX用户&quot;，而是找到<strong>一个特定的人群</strong>，他们的需求更痛、更具体。</p><p><strong>第一步：列出所有可能的细分人群</strong></p><p>针对你的产品概念，列出所有可能的人群。</p><p><strong>第二步：评估每个人群的商业价值</strong></p><table tabindex="0"><thead><tr><th>评估维度</th><th>说明</th></tr></thead><tbody><tr><td>痛点强度</td><td>这个人群的需求是痛点还是痒点？</td></tr><tr><td>付费意愿</td><td>愿意为解决方案付多少钱？</td></tr><tr><td>市场规模</td><td>这个人群有多少人？</td></tr><tr><td>竞争程度</td><td>现有解决方案是否令人满意？</td></tr><tr><td>你对人群的理解</td><td>你是否理解这个人群？是否有接触渠道？</td></tr></tbody></table><p><strong>第三步：选择一个人群深入分析</strong></p><p>选择一个：</p><ul><li>痛点最痛</li><li>付费意愿最强</li><li>你最理解</li><li>竞争相对不激烈</li></ul><p>的人群。</p><div class="tip custom-block"><p class="custom-block-title">切分示例</p><p><strong>产品概念：</strong> 记账 APP</p><table tabindex="0"><thead><tr><th>细分人群</th><th>痛点</th><th>付费意愿</th><th>市场规模</th><th>竞争程度</th></tr></thead><tbody><tr><td>普通上班族</td><td>记录麻烦</td><td>低</td><td>大</td><td>高</td></tr><tr><td>小微企业主</td><td>个人/公司支出混淆</td><td>高</td><td>中</td><td>中</td></tr><tr><td>自由职业者</td><td>收入不稳定，需要预测现金流</td><td>高</td><td>中</td><td>中</td></tr><tr><td>留学生家长</td><td>想知道孩子花多少钱，但孩子不说</td><td>高</td><td>小</td><td>低</td></tr></tbody></table><p><strong>选择：</strong> 留学生家长（痛点最痛，付费意愿高，竞争相对不激烈）</p></div><hr><h3 id="附录c-纵向深挖场景方法" tabindex="-1">附录C：纵向深挖场景方法 <a class="header-anchor" href="#附录c-纵向深挖场景方法" aria-label="Permalink to “附录C：纵向深挖场景方法”">​</a></h3><p>找到人群后，不要停留在单一功能，而是要理解用户的<strong>完整场景</strong>。</p><p><strong>第一步：描述用户的一天</strong></p><p>从早到晚，描述用户在使用你的产品时的完整场景。</p><p><strong>第二步：分析每个场景的痛点</strong></p><p>在每个场景中，用户遇到了什么问题？有什么情绪？</p><p><strong>第三步：找到情绪触点</strong></p><p>恐惧、焦虑、无助、孤独、愤怒、后悔……</p><p><strong>第四步：重构价值</strong></p><p>基于场景和情绪，重构产品价值。</p><div class="tip custom-block"><p class="custom-block-title">深挖示例</p><p><strong>人群：</strong> 产后妈妈</p><table tabindex="0"><thead><tr><th>时间</th><th>场景</th><th>痛点</th><th>情绪</th></tr></thead><tbody><tr><td>早上6点</td><td>宝宝刚睡着，有30分钟空闲</td><td>不知道做什么动作安全</td><td>恐惧</td></tr><tr><td>上午10点</td><td>抱着宝宝哄睡，腰很酸</td><td>手没空，想做修复运动</td><td>焦虑</td></tr><tr><td>下午3点</td><td>宝宝睡觉，想运动</td><td>身体很累，不知道还能不能做</td><td>无助</td></tr><tr><td>晚上8点</td><td>终于有空了</td><td>看着镜子里的自己，觉得人生完蛋了</td><td>抑郁</td></tr><tr><td>长期</td><td>没人理解</td><td>觉得只有自己这么痛苦</td><td>孤独</td></tr></tbody></table><p><strong>重构价值：</strong> 从&quot;健身工具&quot;升级为&quot;康复教练+心理支持者&quot;</p></div><hr><h3 id="附录d-更多从普通idea到好点子的例子" tabindex="-1">附录D：更多从普通idea到好点子的例子 <a class="header-anchor" href="#附录d-更多从普通idea到好点子的例子" aria-label="Permalink to “附录D：更多从普通idea到好点子的例子”">​</a></h3><h4 id="例子一-从-记账app-到-留学资金管家" tabindex="-1">例子一：从&quot;记账APP&quot;到&quot;留学资金管家&quot; <a class="header-anchor" href="#例子一-从-记账app-到-留学资金管家" aria-label="Permalink to “例子一：从&quot;记账APP&quot;到&quot;留学资金管家&quot;”">​</a></h4><p><strong>普通想法：</strong> 自动记账 APP，连接银行卡自动分类消费</p><p><strong>问题：</strong> 市面上已经有随手记、挖财、支付宝账单……</p><p><strong>横向切分：</strong></p><ul><li>留学生家长：想知道孩子在外国花了多少钱，是否超支</li></ul><p><strong>纵向深挖：</strong></p><ul><li>痛点不是&quot;记账&quot;，而是<strong>&quot;失控感&quot;</strong>——孩子花多少钱不知道、花在哪里不知道</li><li>场景：每个月看到信用卡账单，但孩子从来不主动说花了什么</li></ul><p><strong>重构后：</strong> &quot;留学资金管家&quot;——不只是记账，而是让家长对孩子的海外消费&quot;心中有数&quot;</p><p><strong>核心功能：</strong></p><ul><li>子女消费实时同步</li><li>超支预警</li><li>每月消费分析报告</li><li>同类学生消费对比（&quot;你家孩子比平均水平多花 20%&quot;）</li></ul><hr><h4 id="例子二-从-番茄钟工具-到-远程工作证明" tabindex="-1">例子二：从&quot;番茄钟工具&quot;到&quot;远程工作证明&quot; <a class="header-anchor" href="#例子二-从-番茄钟工具-到-远程工作证明" aria-label="Permalink to “例子二：从&quot;番茄钟工具&quot;到&quot;远程工作证明&quot;”">​</a></h4><p><strong>普通想法：</strong> 番茄钟 APP，帮助用户专注工作</p><p><strong>问题：</strong> 手机自带屏幕使用时间、Forest、番茄 ToDo……</p><p><strong>横向切分：</strong></p><ul><li>远程工作者：需要向老板证明&quot;我真的在工作&quot;</li></ul><p><strong>纵向深挖：</strong></p><ul><li>痛点不是&quot;不专注&quot;，而是<strong>&quot;信任危机&quot;</strong>——老板看不到我，怎么证明我在工作？</li><li>场景：每天下班，老板问&quot;今天工作怎么样？&quot;，没法证明</li></ul><p><strong>重构后：</strong> &quot;远程工作证明&quot;——帮远程工作者建立与雇主的信任</p><p><strong>核心功能：</strong></p><ul><li>自动工作时间追踪</li><li>生产力报告</li><li>屏幕活动摘要（隐私保护版）</li><li>每天自动生成&quot;工作报告&quot;，发送给上级</li></ul><hr><h4 id="例子三-从-二手书交易-到-绘本图书馆" tabindex="-1">例子三：从&quot;二手书交易&quot;到&quot;绘本图书馆&quot; <a class="header-anchor" href="#例子三-从-二手书交易-到-绘本图书馆" aria-label="Permalink to “例子三：从&quot;二手书交易&quot;到&quot;绘本图书馆&quot;”">​</a></h4><p><strong>普通想法：</strong> 二手书交易平台</p><p><strong>问题：</strong> 多抓鱼、闲书、孔夫子旧书网……</p><p><strong>横向切分：</strong></p><ul><li>宝妈群体：孩子绘本看完就闲置，但买新的很贵</li></ul><p><strong>纵向深挖：</strong></p><ul><li>痛点不是&quot;买书贵&quot;，而是<strong>&quot;绘本生命周期短&quot;</strong>——孩子3岁看的书，4岁就不看了</li><li>场景：家里堆满了绘本，孩子都不看了，但扔掉可惜</li></ul><p><strong>重构后：</strong> &quot;绘本图书馆送到家&quot;——不是卖二手书，而是提供绘本的&quot;使用权租赁&quot;</p><p><strong>核心功能：</strong></p><ul><li>绘本订阅制（每月寄5本适龄绘本，看完寄回换新的）</li><li>阅读进度追踪</li><li>适龄推荐</li><li>消毒保障</li></ul><hr><h3 id="附录e-ai对话打磨产品概念的5步法" tabindex="-1">附录E：AI对话打磨产品概念的5步法 <a class="header-anchor" href="#附录e-ai对话打磨产品概念的5步法" aria-label="Permalink to “附录E：AI对话打磨产品概念的5步法”">​</a></h3><p>通过多轮 AI 对话，把普通的 idea 逐步打磨成可落地的精准产品概念。</p><p><strong>操作：</strong></p><ul><li>描述你的初步想法（哪怕很粗糙）</li><li>告诉 AI 你的担忧（竞争激烈、不知道怎么差异化等）</li></ul><p><strong>提示词：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想做一个 [产品概念]，</span></span>
<span class="line"><span>但我发现 [问题/担忧]。</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>让 AI 帮你制定最小可行产品计划</li><li>讨论技术实现难度和成本</li><li>设定验证指标</li></ul><p><strong>提示词：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请帮我：</span></span>
<span class="line"><span>1. 规划一个 MVP</span></span>
<span class="line"><span>2. 给出具体的技术实现建议</span></span>
<span class="line"><span>3. 估算成本</span></span>
<span class="line"><span>4. 设定验证指标</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>技术实现难度？</li><li>内容制作成本？</li><li>推广成本？</li><li>用户获取难度？</li></ul><p><strong>提示词：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我担心：</span></span>
<span class="line"><span>1. [担忧1]</span></span>
<span class="line"><span>2. [担忧2]</span></span>
<span class="line"><span>3. [担忧3]</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>针对你的担忧，给出具体建议</li><li>多个方案对比，选择最优</li><li>成本估算</li></ul><p><strong>提示词：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>针对我的担忧，请给出具体的解决方案。</span></span></code></pre></div><p><strong>操作：</strong></p><ul><li>整理一个清晰的行动计划</li><li>设定验证指标</li><li>如果达不到，及时调整方向</li></ul><p><strong>提示词：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请帮我整理一个清晰的行动计划。</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">关键技巧</p><ul><li><strong>多轮对话：</strong> 不要期待一次对话就得到完美答案，多轮迭代</li><li><strong>提供信息：</strong> 告诉 AI 你的观察、经历、身边人的反馈</li><li><strong>质疑 AI：</strong> 如果 AI 的建议不合理，及时指出</li><li><strong>聚焦执行：</strong> 最后一定要落到具体的行动计划</li></ul></div><hr><h3 id="附录f-需求验证清单" tabindex="-1">附录F：需求验证清单 <a class="header-anchor" href="#附录f-需求验证清单" aria-label="Permalink to “附录F：需求验证清单”">​</a></h3><p>在决定投入时间开发之前，用以下清单验证你的想法——<strong>核心问题是：用户会为此买单吗？</strong></p><div class="tip custom-block"><p class="custom-block-title">需求验证清单</p><p><strong>1. 用户画像清晰度</strong></p><ul><li>☐ 能否用一句话描述目标用户？</li><li>☐ 能否说出他们目前的替代方案是什么？</li><li>☐ 能否描述他们使用场景的具体细节？</li><li>☐ 这个人群有付费能力吗？</li></ul><p><strong>2. 痛点强度评估</strong></p><ul><li>☐ 用户现在解决这个问题要付出什么代价？（时间/金钱/精力）</li><li>☐ 如果不解决这个问题，会有什么后果？</li><li>☐ 用户是否已经在寻找解决方案？</li><li>☐ 用户愿意为解决这个问题付多少钱？</li></ul><p><strong>3. 解决方案差异化</strong></p><ul><li>☐ 和现有方案相比，你的优势是什么？</li><li>☐ 这个优势是否足够让用户愿意切换？</li><li>☐ 大平台要复制你的功能，难度大吗？</li><li>☐ 你的差异化是否足以支撑用户付费？</li></ul><p><strong>4. 商业模式可行性</strong></p><ul><li>☐ 用户愿意为此付费吗？付多少？（一定要实际测试）</li><li>☐ 获客成本大概是多少？</li><li>☐ 用户生命周期价值（LTV）能否覆盖获客成本（CAC）？</li><li>☐ 有没有其他变现方式？（广告、增值服务、B端等）</li></ul><p><strong>5. 快速验证方案</strong></p><ul><li>☐ 能否用最小成本（1-2 周）做出可测试的原型？</li><li>☐ 能否找到 10 个目标用户进行访谈？</li><li>☐ 能否设计一个实验验证核心假设？</li><li>☐ 能否让用户预付定金验证付费意愿？</li></ul></div><p><strong>不要问&quot;你会用这个产品吗？&quot;</strong> 这种问题得到的都是假阳性回答。</p><p><strong>要问：</strong></p><ul><li>&quot;你现在怎么解决这个问题？&quot;（了解真实行为）</li><li>&quot;最近一周，这个问题让你困扰了几次？&quot;（了解频率）</li><li>&quot;如果有一个解决方案，但需要你改变现在的习惯，你愿意吗？&quot;（了解改变成本）</li><li>&quot;如果收费 XX 元，你会买吗？&quot;（了解付费意愿）</li></ul><p><strong>最好的验证：</strong> 让用户预付定金。说愿意付费的人很多，真正掏钱的人才是你的目标用户。</p><p><strong>关键指标：</strong></p><ul><li>愿意付定金的用户比例 &gt; 10%：需求真实，值得投入</li><li>愿意付定金的用户比例 5-10%：需求存在，但需要打磨</li><li>愿意付定金的用户比例 &lt; 5%：需求不成立，或产品概念有问题</li></ul><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to “本章小结”">​</a></h2><p>在这一章，我们通过小明的故事，学习了如何用产品经理的视角审视产品想法——<strong>核心始终围绕：用户会为此买单吗？</strong></p><div class="info custom-block"><p class="custom-block-title">核心要点</p><p><strong>1. 真需求的三个标准：</strong></p><ul><li>用户愿意为之付费（最重要的标准）</li><li>用户愿意为之改变行为</li><li>没有解决方案时用户会损失很大</li></ul><p><strong>2. 从普通 idea 到有人买单的产品的路径：</strong></p><ul><li><strong>横向切分：</strong>找到特定人群，越细分付费意愿越强</li><li><strong>纵向深挖：</strong>理解完整场景，解决情绪而不只是功能</li><li><strong>价值重构：</strong>从工具进化为解决方案，建立付费理由</li></ul><p><strong>3. 避开假需求的陷阱：</strong></p><ul><li>解决伪痛点（痒点而非痛点）</li><li>市场规模太小，无法支撑商业模式</li><li>解决方案比问题还复杂</li></ul><p><strong>4. 验证付费意愿的方法：</strong></p><ul><li>找到 10 个目标用户深度访谈</li><li>让用户预付定金验证真实意愿</li><li>愿意付定金的用户比例 &gt; 10% 才值得投入</li></ul><p><strong>5. 用 AI 对话打磨产品概念：</strong></p><ul><li>多轮迭代，不断优化</li><li>聚焦执行，落到行动计划</li><li>设定验证指标，及时调整</li></ul></div><p><strong>记住：</strong> 好的产品经理不是凭空创造需求，而是发现那些<strong>被忽视、被低估、被错误满足</strong>的真实需求，并找到让用户愿意为之买单的方式。</p><p>在下一章，我们将带着经过验证的想法，开始学习如何用 AI IDE 把它变成可交互的产品原型。</p>`,338))])}}});export{P as __pageData,m as default};
